import{c as a,Q as n,j as t,m as p}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"printf","description":"","frontmatter":{},"headers":[{"level":1,"title":"printf","slug":"printf"},{"level":2,"title":"产品支持情况","slug":"产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"需要包含的头文件","slug":"需要包含的头文件"},{"level":2,"title":"SIMD调用示例","slug":"simd调用示例"},{"level":2,"title":"SIMD VF调用示例","slug":"simd-vf调用示例"},{"level":2,"title":"SIMT示例","slug":"simt示例"}],"relativePath":"api/Utils-API/调测接口/printf-290.md","filePath":"api/Utils-API/调测接口/printf-290.md"}'),i={name:"api/Utils-API/调测接口/printf-290.md"};function l(e,s,d,o,c,r){return n(),t("div",null,[...s[0]||(s[0]=[p(`<h1 id="printf" tabindex="-1">printf <a class="header-anchor" href="#printf" aria-label="Permalink to &quot;printf&quot;">​</a></h1><h2 id="产品支持情况" tabindex="-1">产品支持情况 <a class="header-anchor" href="#产品支持情况" aria-label="Permalink to &quot;产品支持情况&quot;">​</a></h2><table tabindex="0"><thead><tr><th>产品</th><th>是否支持</th></tr></thead><tbody><tr><td>Ascend 950PR/Ascend 950DT</td><td>√</td></tr><tr><td>Atlas A3 训练系列产品/Atlas A3 推理系列产品</td><td>√</td></tr><tr><td>Atlas A2 训练系列产品/Atlas A2 推理系列产品</td><td>√</td></tr><tr><td>Atlas 200I/500 A2 推理产品</td><td>x</td></tr><tr><td>Atlas 推理系列产品AI Core</td><td>x</td></tr><tr><td>Atlas 推理系列产品Vector Core</td><td>x</td></tr><tr><td>Atlas 训练系列产品</td><td>x</td></tr><tr><td>Kirin X90</td><td>x</td></tr><tr><td>Kirin 9030</td><td>x</td></tr></tbody></table><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>本接口提供SIMD和SIMT编程调试场景下的格式化输出功能。</p><p>在算子Kernel侧的实现代码中，需要输出日志信息时，调用printf接口打印相关内容。</p><div class="caution custom-block github-alert"><p class="custom-block-title">注意</p><p>printf（PRINTF）接口打印功能会对算子实际运行的性能带来一定影响，通常在调测阶段使用。开发者可以按需通过设置ASCENDC_DUMP=0的方式关闭打印功能</p></div><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class... Args&gt;</span></span>
<span class="line"><span>__aicore__ inline void printf( const __gm__ char* fmt, Args&amp;&amp;... args)</span></span></code></pre></div><p>以下接口为simd_vf中所使用的printf接口，仅支持Ascend 950PR/Ascend 950DT。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>template &lt;class... Args&gt;</span></span>
<span class="line"><span>__simd_callee__ inline void printf( const __ubuf__ char* fmt, Args&amp;&amp;... args)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>fmt</td><td>输入</td><td>格式控制字符串，包含两种类型的对象：普通字符和转换说明。 普通字符将原样不动地打印输出。转换说明并不直接输出而是用于控制printf中参数的转换和打印。每个转换说明都由一个百分号字符（%）开始，以转换说明结束，从而说明输出数据的类型 。 支持的转换类型包括：%d / %ld / %lld / %i / %li / %lli：输出十进制数，支持打印的数据类型：int8_t、int16_t、int32_t、int64_t%f / %F：输出浮点数，支持打印的数据类型：float、half、bfloat16_t%x / %lx / %llx：输出十六进制整数，支持打印的数据类型：int8_t、int16_t、int32_t、int64_t、uint8_t、uint16_t、uint32_t、uint64_t%s：输出字符串%u / %lu /%llu：输出unsigned类型数据，支持打印的数据类型：uint8_t、uint16_t、uint32_t、uint64_t%p：输出指针地址 注意：上文列出的数据类型是NPU域调试支持的数据类型，CPU域调试时，支持的数据类型和C/C++规范保持一致。</td></tr><tr><td>args</td><td>输入</td><td>附加参数，个数和类型可变的参数列表：根据不同的fmt字符串，函数可能需要一系列的附加参数，每个参数包含了一个要被插入的值，替换了fmt参数中指定的每个%标签。参数的个数应与%标签的个数相同。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li><p>本接口不支持打印除换行符之外的其他转义字符。</p></li><li><p>SIMT VF中printf功能需要占用额外的Global Memory空间用于数据缓存，缓存空间大小默认为2MB。您可以通过acl.json中的&quot;simt_printf_fifo_size&quot;字段进行配置，配置范围最小为1MB，最大为64MB。当打印数据量较大时，建议增加缓存空间。</p></li><li><p>printf在SIMT VF中调用，会占用SIMT栈空间，请合理控制调用printf次数，防止SIMT栈溢出。</p></li><li><p>在仿真环境下，使用printf接口会增加算子运行时间，通过在VF代码中判断线程ID，可以仅在部分线程中打印调试信息，减少重复内容的打印，更有利于调试。</p></li><li><p>SIMD场景下，单次调用本接口打印的数据总量不可超过打印大小限制，默认为32KB。使用时应注意，如果超出这个限制，则数据不会被打印。您可以通过acl.json中的&quot;simd_printf_fifo_size_per_core&quot;字段进行配置，配置范围最小为1KB，最大为64MB。当打印数据量较大时，建议增加缓存空间。pytorch调用和算子入图场景暂不支持该配置。</p></li><li><p>SIMD场景下，根据算子执行方式的不同，printf的打印结果输出方式不同。动态图或者单算子直调场景下，待输出内容会被解析并打印在屏幕上；静态图场景下，整图算子需要全下沉到NPU侧执行，无法直接调用接口打印出单个算子的信息，因此需要在模型执行完毕后，将待输出内容落盘在dump文件中，dump文件需要通过工具解析为可读内容。</p><ul><li><p>dump文件落盘路径按照优先级排列如下：</p><ul><li>如果开启了Data Dump功能，dump文件落盘到开发者配置的dump_path路径下。如何开启Dump功能依赖于具体的网络运行方式。以TensorFlow在线推理为例，通过enable_dump、dump_path、dump_mode等参数进行配置。配置方式可参考《TensorFlow 2.6.5模型迁移》中的API参考 &gt; TF Adapter 接口（2.x）&gt; npu.global_options &gt; 配置参数说明章节。</li><li>如果未开启Data Dump功能，但配置了ASCEND_WORK_PATH环境变量，dump文件落盘到ASCEND_WORK_PATH下的printf目录下。</li><li>如果未开启Data Dump功能也没有配置ASCEND_WORK_PATH环境变量，dump文件落盘到当前程序执行目录下的printf路径下。</li></ul></li><li><p>落盘dump文件需要使用工具解析为用户可读内容：</p><p>使用show_kernel_debug_data工具将dump二进制文件解析为用户可读内容，命令格式如下。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>show_kernel_debug_data  bin_file  output_dir</span></span></code></pre></div></li></ul></li><li><p>由于在simd vf中不能直接访问gm地址，因此使用simd vf中的printf时，需要先定义一个ubuf的字符串，该字符串即为原来的fmt变量。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__ubuf__ const char* fmt = &quot;simd vf: int=%d, uint=%u, float=%f, string=%s\\n&quot;;</span></span></code></pre></div></li></ul><h2 id="需要包含的头文件" tabindex="-1">需要包含的头文件 <a class="header-anchor" href="#需要包含的头文件" aria-label="Permalink to &quot;需要包含的头文件&quot;">​</a></h2><p>使用该接口需要包含&quot;utils/debug/asc_printf.h&quot;头文件。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;utils/debug/asc_printf.h&quot;</span></span></code></pre></div><h2 id="simd调用示例" tabindex="-1">SIMD调用示例 <a class="header-anchor" href="#simd调用示例" aria-label="Permalink to &quot;SIMD调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;utils/debug/asc_printf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// SIMD printf</span></span>
<span class="line"><span>__global__ __mix__(1, 2) void hello_world()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    // print string</span></span>
<span class="line"><span>    printf(&quot;hello world device\\n&quot;);</span></span>
<span class="line"><span>    // print int</span></span>
<span class="line"><span>    printf(&quot;fmt string int: %d\\n&quot;, 0x123);</span></span>
<span class="line"><span>    // print float</span></span>
<span class="line"><span>    float b = 3.14;</span></span>
<span class="line"><span>    printf(&quot;fmt string float: %f\\n&quot;, b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>NPU模式下，程序运行时打印效果如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>hello world device</span></span>
<span class="line"><span>fmt string int: 291</span></span>
<span class="line"><span>fmt string float: 3.140000</span></span>
<span class="line"><span>hello world device</span></span>
<span class="line"><span>fmt string int: 291</span></span>
<span class="line"><span>fmt string float: 3.140000</span></span>
<span class="line"><span>hello world device</span></span>
<span class="line"><span>fmt string int: 291</span></span>
<span class="line"><span>fmt string float: 3.140000</span></span>
<span class="line"><span>hello world device</span></span>
<span class="line"><span>fmt string int: 291</span></span>
<span class="line"><span>fmt string float: 3.140000</span></span>
<span class="line"><span>......</span></span></code></pre></div><h2 id="simd-vf调用示例" tabindex="-1">SIMD VF调用示例 <a class="header-anchor" href="#simd-vf调用示例" aria-label="Permalink to &quot;SIMD VF调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span>#include &quot;utils/debug/asc_printf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>__simd_vf__ inline void SimdVfPrint()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    __ubuf__ const char* fmt = &quot;simd vf: int=%d, uint=%u, float=%f, string=%s\\n&quot;;</span></span>
<span class="line"><span>    printf(fmt, 1, 2U, 5.0f, &quot;AscendC&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>NPU模式下，程序运行时打印效果如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>simd vf: int=1, uint=2, float=5.000000, string=AscendC</span></span>
<span class="line"><span>simd vf: int=1, uint=2, float=5.000000, string=AscendC</span></span>
<span class="line"><span>simd vf: int=1, uint=2, float=5.000000, string=AscendC</span></span>
<span class="line"><span>......</span></span></code></pre></div><h2 id="simt示例" tabindex="-1">SIMT示例 <a class="header-anchor" href="#simt示例" aria-label="Permalink to &quot;SIMT示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>#include &quot;kernel_operator.h&quot;</span></span>
<span class="line"><span>#include &quot;simt_api/asc_simt.h&quot;</span></span>
<span class="line"><span>#include &quot;utils/debug/asc_printf.h&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// asc_vf_call调用时dim3参数：dim3(8, 2, 8)</span></span>
<span class="line"><span>__simt_vf__ __launch_bounds__(128) inline void SimtCompute()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    int x = threadIdx.x;</span></span>
<span class="line"><span>    int y = threadIdx.y;</span></span>
<span class="line"><span>    int z = threadIdx.z;</span></span>
<span class="line"><span>    printf(&quot;simt vf: d: (%d, %d, %d), f: %f, s: %s\\n&quot;, x, y, z, 3.14f, &quot;pass&quot;);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>NPU模式下，程序运行时打印效果如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>simt vf: d: (0, 0, 0), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 1), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 2), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 3), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 4), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 5), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 6), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 0, 7), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 1, 0), f: 3.140000, s: pass</span></span>
<span class="line"><span>simt vf: d: (0, 1, 1), f: 3.140000, s: pass</span></span>
<span class="line"><span>......</span></span></code></pre></div>`,32)])])}const f=a(i,[["render",l]]);export{h as __pageData,f as default};
